import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.BVRek7U2.js";const g=JSON.parse('{"title":"create-kyro CLI Scaffolder","description":"","frontmatter":{},"headers":[],"relativePath":"packages/create-kyro.md","filePath":"packages/create-kyro.md","lastUpdated":1784680854000}'),s={name:"packages/create-kyro.md"};function o(n,e,d,c,r,p){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="create-kyro-cli-scaffolder" tabindex="-1">create-kyro CLI Scaffolder <a class="header-anchor" href="#create-kyro-cli-scaffolder" aria-label="Permalink to &quot;create-kyro CLI Scaffolder&quot;">​</a></h1><p><code>create-kyro</code> is an interactive scaffolding command-line utility designed to set up a clean, running Kyro CMS workspace in seconds.</p><hr><h2 id="_1-quick-scaffolding" tabindex="-1">1. Quick Scaffolding <a class="header-anchor" href="#_1-quick-scaffolding" aria-label="Permalink to &quot;1. Quick Scaffolding&quot;">​</a></h2><p>To start the interactive prompt, execute:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">pnpm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> kyro@latest</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-cms-project</span></span></code></pre></div><h3 id="supported-package-managers" tabindex="-1">Supported Package Managers <a class="header-anchor" href="#supported-package-managers" aria-label="Permalink to &quot;Supported Package Managers&quot;">​</a></h3><p>The CLI detects your running terminal manager automatically and scaffolds lockfiles accordingly:</p><ul><li><code>pnpm</code> (Recommended)</li><li><code>npm</code></li><li><code>yarn</code></li><li><code>bun</code></li></ul><hr><h2 id="_2-interactive-prompts-setup-flow" tabindex="-1">2. Interactive Prompts &amp; Setup Flow <a class="header-anchor" href="#_2-interactive-prompts-setup-flow" aria-label="Permalink to &quot;2. Interactive Prompts &amp; Setup Flow&quot;">​</a></h2><p>When launched, <code>create-kyro</code> guides you through a series of structural configurations:</p><ol><li><strong>Project Location</strong>: Specify the directory to initialize (defaults to the current path <code>./</code>).</li><li><strong>Starter Template Selection</strong>: <ul><li><code>Blog</code>: Configures collections for pages, articles, authors, and tag metadata.</li><li><code>E-commerce</code>: Sets up products, variants, orders, inventories, and customer accounts.</li><li><code>Minimal</code>: Scaffolds a single, simple collection with a title and content field for custom builds.</li><li><code>Kitchen Sink</code>: Registers every available collection and template for discovery.</li></ul></li><li><strong>Database Selection</strong>: <ul><li><code>SQLite (Local)</code>: Automatically sets up Node&#39;s native <code>DatabaseSync</code> for immediate offline dev.</li><li><code>PostgreSQL</code>: Scaffolds a Drizzle Postgres schema structure.</li><li><code>MongoDB</code>: Pre-sets environment variables and configurations for NoSQL.</li></ul></li><li><strong>Auto-Install Dependencies</strong>: Opt-in to install all <code>package.json</code> dependencies automatically.</li></ol><hr><h2 id="_3-cli-command-options" tabindex="-1">3. CLI Command Options <a class="header-anchor" href="#_3-cli-command-options" aria-label="Permalink to &quot;3. CLI Command Options&quot;">​</a></h2><p>You can bypass interactive prompts by passing direct flags:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create-kyro@latest</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-project</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --template</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> blog</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --db</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> sqlite</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --install</span></span></code></pre></div><h3 id="available-command-parameters" tabindex="-1">Available Command Parameters <a class="header-anchor" href="#available-command-parameters" aria-label="Permalink to &quot;Available Command Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Flag Option</th><th style="text-align:left;">Allowed Inputs</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-t, --template</code></td><td style="text-align:left;"><code>blog</code>, <code>ecommerce</code>, <code>minimal</code>, <code>kitchen-sink</code></td><td style="text-align:left;">Selection for starting collection structures</td></tr><tr><td style="text-align:left;"><code>-d, --db</code></td><td style="text-align:left;"><code>sqlite</code>, <code>postgres</code>, <code>mongodb</code></td><td style="text-align:left;">Selection of database adapter configuration</td></tr><tr><td style="text-align:left;"><code>-i, --install</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Installs npm dependencies automatically</td></tr><tr><td style="text-align:left;"><code>-y, --yes</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Bypasses all prompt checks and uses default settings</td></tr><tr><td style="text-align:left;"><code>--help</code></td><td style="text-align:left;">None</td><td style="text-align:left;">Lists command parameters</td></tr></tbody></table>',19)])])}const m=t(s,[["render",o]]);export{g as __pageData,m as default};
